def search(arr):
    """
    Function to find the element that appears only once in a sorted array.
    :param arr: List[int] - A sorted array where every element except one appears twice.
    :return: int - The element that appears only once.
    """
    low, high = 0, len(arr) - 1

    while low < high:
        mid = low + (high - low) // 2

        # Check if mid is at the correct position
        if mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                low = mid + 2
            else:
                high = mid
        else:
            if arr[mid] == arr[mid - 1]:
                low = mid + 1
            else:
                high = mid

    return arr[low]

# Example test
assert search([1, 1, 2, 2, 3]) == 3
