def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    def is_amicable(a):
        b = sum_of_divisors(a)
        return a != b and sum_of_divisors(b) == a

    total_sum = 0
    for number in range(2, limit + 1):
        if is_amicable(number):
            total_sum += number

    return total_sum

# Test
assert amicable_numbers_sum(999) == 504
