def find_length(binary_string):
    def max_diff_subarray(arr):
        max_diff = float('-inf')
        current_diff = 0

        for num in arr:
            current_diff += num
            if current_diff > max_diff:
                max_diff = current_diff
            if current_diff < 0:
                current_diff = 0

        return max_diff

    # Convert binary string to an array where 0 -> +1 and 1 -> -1
    diff_array = [1 if char == '0' else -1 for char in binary_string]

    # Find the maximum difference using Kadane's algorithm
    return max_diff_subarray(diff_array)

# Example test
assert find_length("11000010001") == 6
