def merge_dictionaries_three(dict1, dict2, dict3):
    # Initialize an empty dictionary to store the merged results
    merged_dict = {}

    # Define a helper function to add entries to merged_dict
    def add_to_merged_dict(d):
        for key, value in d.items():
            if key not in merged_dict:
                merged_dict[key] = value

    # Add entries from each dictionary to the merged dictionary
    add_to_merged_dict(dict1)
    add_to_merged_dict(dict2)
    add_to_merged_dict(dict3)

    return merged_dict

